arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print(d); sys.exit(1)
for u in d['members']:
    real = u.get('real_name') or u.get('profile',{}).get('display_name') or ''
    if 'diego' in real.lower() or 'alvarez' in real.lower():
        print(u['id'], '|', real, '|', u.get('profile',{}).get('display_name'))
"

